    fn staging_info(&self) -> std::result::Result<(u64, u64), String> {
        let mut cached = self
            .staging_info
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        if let Some(info) = *cached {
            return Ok(info);
        }
        let info = self.executor.staging_info()?;
        *cached = Some(info);
        Ok(info)
    }

